const { bodyContent, folderFiles, readmeFiles } = items[0].json;

// 1. Hub document end index
const endIndex = (bodyContent || []).reduce((max, el) => Math.max(max, el.endIndex || 0), 0);

// 2. Folder ID → name map
const folderMap = {};
for (const f of (folderFiles || [])) {
  if (f.id && f.name) folderMap[f.id] = f.name;
}

// 3. Classify READMEs
const ROOT_PREFIXES = ['00_', '01_', '02_', '03_', '04_', '05_', '99_'];
const SKIP_TERMS = ['Drive README Tracker', '00_START-HERE', 'ADMIN - Doc', 'Organisation'];
const rootReadmes = [];
const swpReadmes = [];

for (const r of (readmeFiles || [])) {
  if (SKIP_TERMS.some(s => r.name.includes(s))) continue;
  const parentId = r.parents && r.parents[0];
  const parentName = folderMap[parentId] || '';
  const entry = {
    name: r.name,
    id: r.id,
    parentName,
    url: `https://docs.google.com/document/d/${r.id}/edit`
  };
  if (ROOT_PREFIXES.some(p => parentName.startsWith(p))) {
    rootReadmes.push(entry);
  } else if (/schoolsWP/i.test(parentName)) {
    swpReadmes.push(entry);
  }
}

rootReadmes.sort((a, b) => a.parentName.localeCompare(b.parentName));
swpReadmes.sort((a, b) => a.parentName.localeCompare(b.parentName));

// 4. Build text segments [text, paraStyle, linkUrl]
const H1 = 'HEADING_1', H2 = 'HEADING_2', H3 = 'HEADING_3', N = 'NORMAL_TEXT';
const today = new Date().toISOString().slice(0, 10);
const segs = [];
const push = (text, style, link) => segs.push([text, style || N, link || null]);

push('README \u2014 Hub Drive\n', H1);
push('Point d\u2019entr\u00e9e unique du Google Drive de Micha\u00ebl KIHL\n');
push(`Mis \u00e0 jour : ${today}\n`);
push('\n');

push('Structure g\u00e9n\u00e9rale\n', H2);
push('Mon Drive/\n');
push('\u251c\u2500\u2500 00_Admin/       \u2192 Finances, l\u00e9gal, administratif, outils\n');
push('\u251c\u2500\u2500 01_Projets/     \u2192 Projets actifs (schoolsWP, Petit Papier Magique\u2026)\n');
push('\u2502   \u2514\u2500\u2500 schoolsWP/ \u2192 Projet principal\n');
push('\u251c\u2500\u2500 02_Ressources/  \u2192 Biblioth\u00e8ques r\u00e9utilisables (templates, formations\u2026)\n');
push('\u251c\u2500\u2500 03_Clients/     \u2192 Un sous-dossier par client\n');
push('\u251c\u2500\u2500 04_Personnel/   \u2192 Documents personnels et RH\n');
push('\u2514\u2500\u2500 99_Archives/    \u2192 Tout ce qui n\u2019est plus actif (lecture seule)\n');
push('\n');

push('Index des dossiers\n', H2);
push('Cliquer sur un lien pour ouvrir le README du dossier correspondant.\n');
push('\n');

if (rootReadmes.length > 0) {
  push('Dossiers racine\n', H3);
  for (const r of rootReadmes) {
    push(r.parentName.padEnd(20) + '\u2192 ');
    push(r.name + '\n', N, r.url);
  }
}

if (swpReadmes.length > 0) {
  push('\n');
  push('Projet schoolsWP\n', H3);
  for (const r of swpReadmes) {
    push('schoolsWP / ' + r.parentName.padEnd(22) + '\u2192 ');
    push(r.name + '\n', N, r.url);
  }
}

push('\n');
push('Conventions de nommage\n', H2);
push('Dossiers : NN_NomDossier\n');
push('  Exemple : 01_Projets, 02_Ressources\n');
push('\n');
push('Fichiers : AAAA-MM-JJ \u2013 Sujet \u2013 Type.ext\n');
push('  Exemple : 2026-03-14 \u2013 Devis Client Dupont \u2013 V1.pdf\n');
push('\n');
push('\u2192 Guide complet : ');
const adminR = rootReadmes.find(r => /admin/i.test(r.name));
const adminUrl = adminR ? adminR.url : 'https://docs.google.com/document/d/1dwdf6wUAMqMx_RxjDINfyzTwnCAc-KVScFDwJVzKezo/edit';
push('README \u2014 Admin', N, adminUrl);
push(' (00_Admin/)\n');
push('\n');

push('R\u00e8gles g\u00e9n\u00e9rales\n', H2);
push('\u2022 Un document = un seul emplacement. Pas de doublons.\n');
push('\u2022 Rien \u00e0 la racine. Tout fichier doit \u00eatre dans un dossier.\n');
push('\u2022 Les archives restent dans 99_Archives \u2014 jamais supprim\u00e9es.\n');
push('\u2022 Appliquer la nomenclature \u00e0 tout nouveau fichier.\n');

// 5. Compute character positions
const fullText = segs.map(s => s[0]).join('');
let pos = 1;
const segPos = segs.map(([text, style, link]) => {
  const start = pos;
  pos += text.length;
  return { start, end: pos, style, link, text };
});

// 6. Build batchUpdate requests
const requests = [];
if (endIndex > 2) {
  requests.push({ deleteContentRange: { range: { startIndex: 1, endIndex: endIndex - 1 } } });
}
requests.push({ insertText: { location: { index: 1 }, text: fullText } });

for (const { start, end, style } of segPos) {
  if (style !== N) {
    requests.push({ updateParagraphStyle: {
      range: { startIndex: start, endIndex: end },
      paragraphStyle: { namedStyleType: style },
      fields: 'namedStyleType'
    }});
  }
}

for (const { start, end, link, text } of segPos) {
  if (link) {
    const linkEnd = text.endsWith('\n') ? end - 1 : end;
    requests.push({ updateTextStyle: {
      range: { startIndex: start, endIndex: linkEnd },
      textStyle: {
        link: { url: link },
        foregroundColor: { color: { rgbColor: { red: 0.067, green: 0.322, blue: 0.729 } } },
        underline: true
      },
      fields: 'link,foregroundColor,underline'
    }});
  }
}

return [{
  json: {
    requestsJson: JSON.stringify({ requests }),
    meta: {
      rootCount: rootReadmes.length,
      swpCount: swpReadmes.length,
      totalRequests: requests.length,
      updatedAt: today
    }
  }
}];
